import{_ as a,a0 as i,w as m,s as d,ao as l,I as t,a1 as n,A as p,x as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Web 浏览器中启用深色模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Web 浏览器中启用深色模式 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Web 浏览器中启用深色模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Web 浏览器中启用深色模式 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221030.0 ⭐️ How to Enable Dark Mode in Web Browser","title":"如何在 Web 浏览器中启用深色模式","tag":"202211","desc":""},"relativePath":"202211/20221030.0 ⭐️ How to Enable Dark Mode in Web Browser.md","filePath":"[post].md"}'),s={name:"202211/20221030.0 ⭐️ How to Enable Dark Mode in Web Browser.md"};function u(b,e,f,h,g,w){const o=i("Link");return m(),d("div",null,[e[22]||(e[22]=l('<h1 id="如何在-web-浏览器中启用深色模式" tabindex="-1">如何在 Web 浏览器中启用深色模式 <a class="header-anchor" href="#如何在-web-浏览器中启用深色模式" aria-label="Permalink to “如何在 Web 浏览器中启用深色模式”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/08/110615dax28a8fhx13hxhi.jpg" alt=""></p><blockquote><p>本指南旨在帮助你在 Firefox、Chrome、Chromium 和 Edge 等流行的网页浏览器中启用深色模式。</p></blockquote><p>我们都喜欢深色模式。与标准浅色模式相比，许多人更喜欢它。许多桌面应用原生提供深色模式，而一些应用则是通过桌面环境的底层模式适应深色模式。</p><p>不可否认，我们都在网页浏览器上花费了很多时间。我们很少使用桌面应用（除非你从事专门的工作，例如视频编辑等）。因此，当你花费大量时间在浏览器中阅读和学习时，你始终可以选择深色模式。不过，对于网页浏览器，启用深色模式的方法略有不同。</p><p>本指南为你提供了在 Firefox、Chromium、Chrome 和 Edge 浏览器中启用深色模式的简单步骤。</p><h3 id="在网页浏览器中启用深色模式" tabindex="-1">在网页浏览器中启用深色模式 <a class="header-anchor" href="#在网页浏览器中启用深色模式" aria-label="Permalink to “在网页浏览器中启用深色模式”">​</a></h3><h4 id="在-firefox-中启用深色模式" tabindex="-1">在 Firefox 中启用深色模式 <a class="header-anchor" href="#在-firefox-中启用深色模式" aria-label="Permalink to “在 Firefox 中启用深色模式”">​</a></h4><p>打开 Firefox 并点击右上角的菜单。</p><p>单击 “<ruby>设置<rt>Settings</rt></ruby> &gt; <ruby>扩展和主题<rt>Extension and Themes</rt></ruby>”。</p><p>选择 “<ruby>深色主题<rt>Dark Theme</rt></ruby>” 并点击 “<ruby>启用<rt>enable</rt></ruby>”。你应该会看到深色模式已应用于 Firefox。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Enable-dark-mode-in-Firefox.jpg" alt="Enable dark mode in Firefox"></p><p><em>在 Firefox 浏览器中启用深色模式</em></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Firefox-in-Dark-Mode-1024x423.jpg" alt="Firefox in Dark Mode"></p><p><em>深色模式下的 Firefox</em></p><p>要将其还原，请按照相同的步骤并选择浅色主题。</p><h4 id="chromium-和-chrome-中的深色模式" tabindex="-1">Chromium 和 Chrome 中的深色模式 <a class="header-anchor" href="#chromium-和-chrome-中的深色模式" aria-label="Permalink to “Chromium 和 Chrome 中的深色模式”">​</a></h4><p>默认情况下，Chromium 或 Chrome 不会预安装任何深色主题。因此，你需要前往 Chrome 应用商店并下载你想要的深色主题。对于本指南，我会推荐超过一百万用户使用的 “Morpheon Dark” 主题。</p><p>从 Chromium 浏览器打开 Morpheon Dark 主题页面（以下链接）。</p>',19)),t("blockquote",null,[t("p",null,[t("strong",null,[n(o,{href:"https://chrome.google.com/webstore/detail/morpheon-dark/mafbdhjdkjnoafhfelkjpchpaepjknad?hl=en-GB"},{default:p(()=>[...e[0]||(e[0]=[r("Chrome 应用商店中的 Morpheon Dark 主题",-1)])]),_:1})])])]),e[23]||(e[23]=t("p",null,[r("点击 “"),t("ruby",null,[r("添加到 Chrome"),t("rt",null,"Add To Chrome")]),r("” 按钮。它应该会在 Chrome 中启用。")],-1)),t("p",null,[e[2]||(e[2]=r("你可能想探索 Chrome 应用店中提供的其他深色或浅色主题。 ",-1)),n(o,{href:"https://chrome.google.com/webstore/category/collection/dark_themes"},{default:p(()=>[...e[1]||(e[1]=[r("访问此页面获取所有深色主题的集合",-1)])]),_:1}),e[3]||(e[3]=r("。",-1))]),e[24]||(e[24]=t("p",null,"但是，你应该要记住的一件事是：此主题不会更改设置或上下文菜单，这是显而易见的。因为它只是改变了浏览器窗口，而这些菜单（有时）是操作系统本身的一部分。",-1)),e[25]||(e[25]=t("p",null,[t("img",{src:"https://www.debugpoint.com/wp-content/uploads/2021/10/Chromium-Dark-Theme-1024x463.jpg",alt:"Chromium Dark Theme"})],-1)),e[26]||(e[26]=t("p",null,[t("em",null,"Chromium 深色主题")],-1)),e[27]||(e[27]=t("p",null,"对 Chrome 浏览器也遵循相同的步骤。",-1)),e[28]||(e[28]=t("h4",{id:"edge-浏览器-–-深色模式",tabindex:"-1"},[r("Edge 浏览器 – 深色模式 "),t("a",{class:"header-anchor",href:"#edge-浏览器-–-深色模式","aria-label":"Permalink to “Edge 浏览器 – 深色模式”"},"​")],-1)),t("p",null,[e[5]||(e[5]=r("但是，",-1)),n(o,{href:"https://www.debugpoint.com/2020/10/how-to-install-edge-ubuntu-linux/"},{default:p(()=>[...e[4]||(e[4]=[r("Edge 浏览器",-1)])]),_:1}),e[6]||(e[6]=r(" 默认带有更好的深色主题。它允许你从设置中使用 GTK+、浅色和深色模式。",-1))]),e[29]||(e[29]=l('<p>打开 Edge 浏览器，点击右上角的三个小点。</p><p>转到 “<ruby>外观<rt>Appearance</rt></ruby>” 并选择 “<ruby>深色<rt>Dark</rt></ruby>”。这样应该就好了。</p><p>Edge 的这种深色主题实现更好，因为它改变了上下文菜单和地址栏。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Edge-in-Dark-Theme-1024x541.jpg" alt="Edge in Dark Theme"></p><p><em>深色主题的 Edge</em></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如果你是高级用户，你可能不需要本指南。你可以自己弄清楚。</p><p>但我们为所有读者涵盖了所有基础到高级教程。许多新的 Linux 用户可能不知道如何在浏览器中启用深色模式。</p><p>所以，就是说，我希望这对你和其他人有帮助。如果你遇到任何问题，请在下面的评论框中告诉我。</p><hr>',10)),t("p",null,[e[8]||(e[8]=r("via: ",-1)),n(o,{href:"https://www.debugpoint.com/dark-mode-browser/"},{default:p(()=>[...e[7]||(e[7]=[r("https://www.debugpoint.com/dark-mode-browser/",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=r("作者：",-1)),n(o,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...e[9]||(e[9]=[r("Arindam",-1)])]),_:1}),e[14]||(e[14]=r(" 选题：",-1)),n(o,{href:"https://github.com/lkxed"},{default:p(()=>[...e[10]||(e[10]=[r("lkxed",-1)])]),_:1}),e[15]||(e[15]=r(" 译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:p(()=>[...e[11]||(e[11]=[r("geekpi",-1)])]),_:1}),e[16]||(e[16]=r(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[12]||(e[12]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=r("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[r("LCTT",-1)])]),_:1}),e[20]||(e[20]=r(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[r("Linux 中国",-1)])]),_:1}),e[21]||(e[21]=r(" 荣誉推出",-1))])])}const T=a(s,[["render",u]]);export{C as __pageData,T as default};
